'use client'

import { useState, type ReactNode } from 'react'
import { Icon } from '@/lib/icon'
import { Button } from '../buttons/Button'
import { Checkbox } from '../controls/Checkbox'
import { Popover } from '../overlays/Popover'
import styles from './ColumnChooser.module.css'

/** A Table column fits as is: only these fields are read. Declared here, not picked from Table, so the chooser installs without it. */
export interface ColumnChooserColumn {
  key: string
  header: ReactNode
  /** The row header names each row, so it cannot be hidden. */
  isRowHeader?: boolean
}

export interface ColumnChooserProps {
  /** Every column, hidden ones included, in table order. */
  columns: ColumnChooserColumn[]
  /** The shown columns' keys. Pair with `onVisibleKeysChange`. */
  visibleKeys?: string[]
  /** Shown at first, uncontrolled, and what Reset brings back. Defaults to every column. */
  defaultVisibleKeys?: string[]
  /** Called with the shown keys, in column order, when a box is ticked or Reset is pressed. */
  onVisibleKeysChange?: (keys: string[]) => void
  /** Also called by Reset, to put back what lives outside the chooser, such as column widths. */
  onReset?: () => void
  /** The button's text and the popup's accessible name. */
  label?: string
  /** The text of the last row, which brings back the default columns. */
  resetLabel?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Where the popup renders instead of `<body>`. */
  container?: HTMLElement | null
  className?: string
}

/** A button that opens a list of a table's columns, each with a checkbox to show or hide it. */
export function ColumnChooser({
  columns,
  visibleKeys,
  defaultVisibleKeys,
  onVisibleKeysChange,
  onReset,
  label = 'Columns',
  resetLabel = 'Reset columns',
  open,
  defaultOpen,
  onOpenChange,
  container,
  className,
}: ColumnChooserProps) {
  // Column order, whatever order the keys came in; the row header always in.
  const ordered = (keys: Set<string>) => columns.filter((c) => c.isRowHeader || keys.has(c.key)).map((c) => c.key)
  const initial = defaultVisibleKeys ? ordered(new Set(defaultVisibleKeys)) : columns.map((c) => c.key)
  const [state, setState] = useState(initial)
  const shown = new Set(visibleKeys ?? state)
  const set = (keys: Set<string>) => {
    const next = ordered(keys)
    setState(next)
    onVisibleKeysChange?.(next)
  }
  const shownCount = columns.filter((c) => shown.has(c.key)).length
  return (
    <Popover
      trigger={
        <Button variant="secondary" appearance="outlined" endIcon={<Icon name="chevron-down" />} className={className}>
          {label}
        </Button>
      }
      aria-label={label}
      className={styles.popup}
      align="end"
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      container={container}
    >
      <div className={styles.list}>
        {columns.map((col) => {
          const checked = col.isRowHeader || shown.has(col.key)
          return (
            // The row is the Checkbox's own label, stretched: a click anywhere on it toggles the box.
            <Checkbox
              key={col.key}
              className={styles.row}
              label={col.header}
              checked={checked}
              // The row header always shows, and so does the last column left.
              disabled={col.isRowHeader || (checked && shownCount <= 1)}
              onCheckedChange={(on) => {
                const next = new Set(shown)
                if (on) next.add(col.key)
                else next.delete(col.key)
                set(next)
              }}
            />
          )
        })}
      </div>
      <div role="separator" className={styles.separator} />
      <button
        type="button"
        className={styles.reset}
        onClick={() => {
          set(new Set(initial))
          onReset?.()
        }}
      >
        {resetLabel}
      </button>
    </Popover>
  )
}

/* The popup is a Listbox's shell, not a Popover's card: 8px above and below
   the rows, none at the sides, so the rows' highlight runs edge to edge.
   Doubled with the role so it wins over Popover's own .popup, whatever
   order the two stylesheets load in. */
[role='dialog'].popup {
  /* Popover's own max-inline-size keeps it inside a narrow screen. */
  inline-size: 15rem;
  padding: var(--space-2) 0;
}

.list {
  display: flex;
  flex-direction: column;
}

/* A column is an Option's row: 6px block and 12px inline padding around a
   20px line, a 32px row. The Checkbox's label is stretched to fill it, so
   the whole row is the click target. */
.row > label,
.reset {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  inline-size: 100%;
  min-block-size: var(--control-md);
  padding: var(--space-1-5) var(--space-3);
}

.row > label:hover:not([data-disabled]),
.reset:hover {
  background: var(--color-background-neutral);
  color: var(--color-text);
}

/* 1px rule, 4px above and below, edge to edge. */
.separator {
  block-size: var(--border-width);
  margin-block: var(--space-1);
  background: var(--color-border);
}

/* Reset reads as one more row: its text starts where the column names do,
   past a checkbox-wide slot. */
.reset {
  margin: 0;
  padding-inline-start: calc(var(--space-3) + var(--choice-box) + var(--space-2));
  border: 0;
  background: transparent;
  color: var(--color-text);
  font: inherit;
  text-align: start;
  cursor: var(--cursor-button);
  outline: none;
}
.reset:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset-inset);
}

/* Rows are 32px; on touch they grow to 44px. They stack edge to edge, so
   an invisible larger area would overlap the next one. */
@media (pointer: coarse) {
  .row > label,
  .reset {
    min-block-size: var(--target-coarse);
  }
}
